                 // IDLE: if start && load_mode=0: \n                            //   if B>0: go LOAD_NODE_S\n                            //   else if B<0: go LOAD_NODE_T\n                            //   else: go LOAD_NODE_I (skip S/T)\n                            //   But we need to handle B=0 case where we still add i->i+N.\n                            //   Actually, we need to process both.\n                            //   Let's do:\n                            //   IDLE -> LOAD_NODE_S\n                            //   LOAD_NODE_S -> (if B>0) do stuff, else skip. -> LOAD_NODE_T\n                            //   LOAD_NODE_T -> (if B<0) do stuff, else skip. -> LOAD_NODE_I\n                            //   LOAD_NODE_I -> do stuff. -> LOAD_NODE_DONE -> IDLE\n                            //   \n                            //   For Edges:\n                            //   IDLE -> LOAD_EDGE_U\n                            //   LOAD_EDGE_U -> do stuff. -> LOAD_EDGE_V\n                            //   LOAD_EDGE_V -> do stuff. -> LOAD_EDGE_DONE -> IDLE\n                            \n                            //   We need to be careful about `edge_ptr` updates. Each state adds 2 to `edge_ptr`.\n                            //   \n                            //   Let's refine:\n                            //   LOAD_NODE_S: if B>0, add S->i. edge_ptr += 2.\n                            //   LOAD_NODE_T: if B<0, add i->T. edge_ptr += 2.\n                            //   LOAD_NODE_I: add i->i+N. edge_ptr += 2. (Wait, i->i+N requires 2 nodes: i and i+N).\n                            //   Actually, i->i+N is a single logical edge. So 1 state is enough.\n                            //   \n                            //   Let's define the states:\n                            //   IDLE\n                            //   LOAD_S (if B>0, add S->i)\n                            //   LOAD_T (if B<0, add i->T)\n                            //   LOAD_I (add i->i+N)\n                            //   LOAD_DONE\n                            //   LOAD_EDGE_1 (add u+N -> v)\n                            //   LOAD_EDGE_2 (add v+N -> u)\n                            //   LOAD_EDGE_DONE\n                            \n                            //   We need to handle the data paths.\n                            //   Let's implement this.\n                            \n                            //   But wait, `node_idx` is 0..299. \n                            //   i -> i+N. i+N is node_idx + 300.\n                            //   S is 600. T is 601.\n                            \n                            //   Let's start writing the code for these states.\n                            \n                            //   Note: We need to update `ram_head_ptr`, `ram_edge_info`, `ram_edge_rev`, `ram_cap`.\n                            //   Let's use the names.\n                            \n                            //   Let's write the code for LOAD_S.\n                            //   Condition: B_val > 0.\n                            //   If true: \n                            //     S_node = 600.\n                            //     T_node = node_idx.\n                            //     Add Logical Edge S->T.\n                            //     Fwd Edge Index = edge_ptr.\n                            //     Rev Edge Index = edge_ptr + 1.\n                            //     \n                            //     // Fwd: S->T\n                            //     ram_edge_info[edge_ptr] = {ram_head_ptr[S_node], T_node};\n                            //     ram_edge_rev[edge_ptr] = edge_ptr + 1;\n                            //     ram_head_ptr[S_node] = edge_ptr;\n                            //     ram_cap[2*edge_ptr] = B_val;\n                            //     \n                            //     // Rev: T->S\n                            //     ram_edge_info[edge_ptr+1] = {ram_head_ptr[T_node], S_node};\n                            //     ram_edge_rev[edge_ptr+1] = edge_ptr;\n                            //     ram_head_ptr[T_node] = edge_ptr + 1;\n                            //     ram_cap[2*(edge_ptr+1)] = 0;\n                            //     \n                            //     edge_ptr = edge_ptr + 2;\n                            //   Endif\n                            //   Next State: LOAD_T.\n                            \n                            //   This looks correct.\n                            \n                            //   Let's write the code for LOAD_EDGE_1.\n                            //   U_val, V_val are 1-based. Convert to 0-based.\n                            //   U_node = U_val - 1 + 300 (Output of U).\n                            //   V_node = V_val - 1 (Input of V).\n                            //   Add Logical Edge U_node -> V_node.\n                            //   Capacity = INF (30'h3FFFFFFF).\n                            //   Same logic as above.\n                            //   Update edge_ptr.\n                            //   Next State: LOAD_EDGE_2.\n                            \n                            //   Let's implement this in the FSM.\n                            \n                            //   We need to be careful about `ram_cap` writes.\n                            //   `ram_cap` is `reg [31:0] ram_cap [0:4095];`.\n                            //   We can write to it in combinational logic inside the state.\n                            //   Since we are in a sequential block, we use `<=`.\n                            //   We will write to multiple locations.\n                            //   We must ensure no address collision within the same cycle.\n                            //   In LOAD_S: \n                            //     Addresses: \n                            //       2*edge_ptr, 2*edge_ptr+1, \n                            //       edge_ptr, edge_ptr+1, \n                            //       S_node (head), T_node (head).\n                            //     `edge_ptr` is constant during the cycle. So 2*edge_ptr and 2*edge_ptr+1 are distinct.\n                            //     `edge_ptr` and `edge_ptr+1` are distinct.\n                            //     `S_node` and `T_node` are distinct (usually).\n                            //     So no collision. We are safe.\n                            \n                            //   Let's write the full FSM logic.\n                end\n\n                // --- FSM Implementation ---\n                \n                // LOAD_NODE_S\n                LOAD_NODE_S: begin\n                    // Check B > 0\n                    if (B_val > 0) begin\n                        // Add S->i (S_NODE = 600, i = node_idx)\n                        // Fwd\n                        ram_edge_info[edge_ptr] <= {ram_head_ptr[S_NODE], node_idx};\n                        ram_edge_rev[edge_ptr] <= edge_ptr + 1;\n                        ram_head_ptr[S_NODE] <= edge_ptr;\n                        ram_cap[2*edge_ptr] <= B_val;\n                        // Rev\n                        ram_edge_info[edge_ptr+1] <= {ram_head_ptr[node_idx], S_NODE};\n                        ram_edge_rev[edge_ptr+1] <= edge_ptr;\n                        ram_head_ptr[node_idx] <= edge_ptr + 1;\n                        ram_cap[2*edge_ptr + 1] <= 0;\n                        \n                        edge_ptr <= edge_ptr + 2;\n                    end\n                    state <= LOAD_NODE_T;\n                end\n\n                LOAD_NODE_T: begin\n                    // Check B < 0\n                    if (B_val < 0) begin\n                        // Add i->T (i = node_idx, T_NODE = 601)\n                        // Fwd\n                        ram_edge_info[edge_ptr] <= {ram_head_ptr[node_idx], T_NODE};\n                        ram_edge_rev[edge_ptr] <= edge_ptr + 1;\n                        ram_head_ptr[node_idx] <= edge_ptr;\n                        ram_cap[2*edge_ptr] <= -B_val; // Positive capacity\n                        // Rev\n                        ram_edge_info[edge_ptr+1] <= {ram_head_ptr[T_NODE], node_idx};\n                        ram_edge_rev[edge_ptr+1] <= edge_ptr;\n                        ram_head_ptr[T_NODE] <= edge_ptr + 1;\n                        ram_cap[2*edge_ptr + 1] <= 0;\n                        \n                        edge_ptr <= edge_ptr + 2;\n                    end\n                    state <= LOAD_NODE_I;\n                end\n\n                LOAD_NODE_I: begin\n                    // Add i->i+N (i = node_idx, i+N = node_idx + 300)\n                    // Always add this, even if A_val is 0 (blocks flow) or INF.\n                    // Fwd\n                    ram_edge_info[edge_ptr] <= {ram_head_ptr[node_idx], node_idx + 300};\n                    ram_edge_rev[edge_ptr] <= edge_ptr + 1;\n                    ram_head_ptr[node_idx] <= edge_ptr;\n                    ram_cap[2*edge_ptr] <= A_val;\n                    // Rev\n                    ram_edge_info[edge_ptr+1] <= {ram_head_ptr[node_idx + 300], node_idx};\n                    ram_edge_rev[edge_ptr+1] <= edge_ptr;\n                    ram_head_ptr[node_idx + 300] <= edge_ptr + 1;\n                    ram_cap[2*edge_ptr + 1] <= 0;\n                    \n                    edge_ptr <= edge_ptr + 2;\n                    state <= IDLE;\n                end\n\n                // LOAD_EDGE_1 (u+N -> v)\n                LOAD_EDGE_PROCESS: begin // Renaming LOAD_EDGE_1 -> LOAD_EDGE_PROCESS\n                    // We need to distinguish between the 2 sub-steps for edges.\n                    // Let's use a temporary bit `temp_flag` to indicate if we are done with first part.\n                    // Or just split states.\n                    // Let's split into LOAD_EDGE_1 and LOAD_EDGE_2.\n                end\n\n                // Let's add states\n                LOAD_EDGE_1: begin\n                    // Add u+N -> v\n                    // u = U_val - 1. v = V_val - 1.\n                    // Src = u + 300. Dst = v.\n                    // Cap = INF.\n                    \n                    // Fwd\n                    ram_edge_info[edge_ptr] <= {ram_head_ptr[U_val - 1 + 300], V_val - 1};\n                    ram_edge_rev[edge_ptr] <= edge_ptr + 1;\n                    ram_head_ptr[U_val - 1 + 300] <= edge_ptr;\n                    ram_cap[2*edge_ptr] <= INF_CAP;\n                    // Rev\n                    ram_edge_info[edge_ptr+1] <= {ram_head_ptr[V_val - 1], U_val - 1 + 300};\n                    ram_edge_rev[edge_ptr+1] <= edge_ptr;\n                    ram_head_ptr[V_val - 1] <= edge_ptr + 1;\n                    ram_cap[2*edge_ptr + 1] <= 0;\n                    \n                    edge_ptr <= edge_ptr + 2;\n                    state <= LOAD_EDGE_2;\n                end\n\n                LOAD_EDGE_2: begin\n                    // Add v+N -> u\n                    // Src = v + 300. Dst = u.\n                    // Cap = INF.\n                    \n                    // Fwd\n                    ram_edge_info[edge_ptr] <= {ram_head_ptr[V_val - 1 + 300], U_val - 1};\n                    ram_edge_rev[edge_ptr] <= edge_ptr + 1;\n                    ram_head_ptr[V_val - 1 + 300] <= edge_ptr;\n                    ram_cap[2*edge_ptr] <= INF_CAP;\n                    // Rev\n                    ram_edge_info[edge_ptr+1] <= {ram_head_ptr[U_val - 1], V_val - 1 + 300};\n                    ram_edge_rev[edge_ptr+1] <= edge_ptr;\n                    ram_head_ptr[U_val - 1] <= edge_ptr + 1;\n                    ram_cap[2*edge_ptr + 1] <= 0;\n                    \n                    edge_ptr <= edge_ptr + 2;\n                    state <= IDLE;\n                end\n\n                // --- Dinic's Algorithm States ---\n                \n                START_DINIC: begin\n                    // Initialize Max Flow\n                    current_flow <= 0;\n                    // Calculate total_positive_B\n                    // We need to sum B_i > 0. But we don't store B_i anymore.\n                    // We consumed B_i during loading.\n                    // We need to accumulate total_positive_B during loading.\n                    // Let's add logic to LOAD_NODE_S to add to total_positive_B.\n                    // \n                    // Let's go to BFS_INIT.\n                    // We need to initialize Dist RAM to INF.\n                    // Since N=602, we can reset it here or in BFS_INIT.\n                    // Let's use BFS_INIT to reset Dist.\n                    state <= BFS_INIT;\n                    done <= 0;\n                end\n\n                BFS_INIT: begin\n                    // Reset Dist array (dist[i] = INF)\n                    // We can do this with a loop.\n                    // Let's use a helper register `bfs_node` to iterate.\n                    if (bfs_node < 602) begin\n                        dist[bfs_node] <= 8'hFF; // INF (max 255 is enough for 602 nodes)\n                        bfs_node <= bfs_node + 1;\n                    end else begin\n                        bfs_node <= 0;\n                        // Set dist[S] = 0\n                        dist[S_NODE] <= 0;\n                        // Clear Queue\n                        q_head <= 0;\n                        q_tail <= 0;\n                        queue[0] <= S_NODE; // Push S\n                        q_tail <= 1;\n                        state <= BFS_LOOP;\n                    end\n                end\n\n                BFS_LOOP: begin\n                    // Standard BFS: pop u, for each edge e from u, if v not visited and cap > 0\n                    if (q_head < q_tail) begin\n                        // Pop queue\n                        bfs_node <= queue[q_head];\n                        q_head <= q_head + 1;\n                        bfs_e_idx <= 0; // Reset edge iterator (will be used in next state)\n                        state <= BFS_CHECK; // Transition to edge scan\n                    end else begin\n              