      \n                // Correction for DFS_UPDATE_PATH (to be implemented):\n                //   stack_ptr --;\n                //   e = stack_edge[stack_ptr];\n                //   cap[e] -= flow.\n                //   cap[rev[e]] += flow.\n                //   current_flow += flow.\n                //   If stack_ptr == 0 -> go DFS_INIT (restart from S).\n                //   Else -> go DFS_UPDATE_PATH (loop).\n\n                // Let's write the final DFS states.\n\n                // State DFS_UPDATE_PATH (Revised)\n                DFS_UPDATE_PATH: begin\n                    if (stack_ptr == 0) begin\n                        // Path fully updated. Restart DFS from S.\n                        // But we might find another path in the same level graph.\n                        // So we go to DFS_INIT.\n                        // However, we should check if we can push more flow.\n                        // DFS_INIT resets flow to INF.\n                        state <= DFS_INIT;\n                    end else begin\n                        // Get edge from stack (which points to the edge leading to the child)\n                        // stack_ptr currently points to the next free slot or top used?\n                        // If we pushed, stack_ptr was incremented. So top is at stack_ptr-1.\n                        // In the code above, we decremented stack_ptr in the backtrack logic.\n                        // Let's standardize: stack_ptr is the number of elements.\n                        // Indices 0 to stack_ptr-1 are used.\n                        \n                        // Wait, in DFS_UPDATE_PATH, we want to pop from the stack.\n                        // So we decrement stack_ptr first, then access.\n                        // If we are in UPDATE_PATH, it means we found T.\n                        // The stack contains edges from S to parent of T.\n                        // The edge connecting to T is NOT on the stack if we didn't push T.\n                        // We pushed the PARENT of T before moving to T.\n                        // So the edge used is `stack_edge[stack_ptr-1]`.\n                        \n                        // Let's do:\n                        // Decrement stack_ptr.\n                        // Get e = stack_edge[stack_ptr].\n                        // Update cap[e].\n                        // Update cap[rev[e]].\n                        // Add to flow.\n                        // Loop.\n                        \n                        // But we need the flow amount. `dfs_flow` is the flow for THIS path.\n                        // It doesn't change during updates.\n                        \n                        // Implementation:\n                        stack_ptr <= stack_ptr - 1;\n                        // We need to use the edge index to update caps.\n                        // We need a temp register for the edge index.\n                        // Let's use `current_edge_ptr`.\n                        current_edge_ptr <= stack_edge[stack_ptr - 1];\n                        \n                        // We need a state to perform the update (since RAM write is sync).\n                        state <= DFS_PERFORM_UPDATE;\n                    end\n                end\n\n                DFS_PERFORM_UPDATE: begin\n                    // Perform the RAM write\n                    // e = current_edge_ptr\n                    // cap[e] -= dfs_flow\n                    // cap[rev[e]] += dfs_flow\n                    \n                    // We need to read `ram_cap` first, modify, write back.\n                    // But since we are in a sequential block, we can just subtract.\n                    // We need to handle the RAM write address.\n                    // We can't read and write to same RAM array in one cycle easily without dual port.\n                    // But we can use `<=` to schedule writes.\n                    // We need to read `ram_cap[2*current_edge_ptr]` and `ram_cap[2*rev[current_edge_ptr]]`.\n                    \n                    // Let's assume we can access them.\n                    // But we need the Rev Index.\n                    // `ram_edge_rev[current_edge_ptr]` gives the index of the reverse edge.\n                    // The reverse capacity is at `2*rev_index`. \n                    // Wait, interleaved: Fwd at 2*k. Rev at 2*k+1? Or Fwd at 2*k, Rev at 2*(k+1)?\n                    // Let's use: Fwd Cap at 2*k, Rev Cap at 2*k+1.\n                    // But we have separate edge objects for fwd and rev.\n                    // Edge 'e' is a logical object. It has a 'rev' pointer to another logical object 'r'.\n                    // Capacity of e is `ram_cap[2*e]`.\n                    // Capacity of r is `ram_cap[2*r]`.\n                    // This is getting confusing.\n                    \n                    // Let's simplify: We have 1 RAM for capacities. \n                    // We will store capacity of edge 'e' at index '2*e'.\n                    // We will store capacity of reverse edge at index '2*e + 1'.\n                    // NO. We have 'e' and 'r' as separate indices in the adjacency list.\n                    // If 'e' points to 'r' as rev, then 'r' points to 'e' as rev.\n                    // We update Cap(e) and Cap(r).\n                    // Cap(e) is at index `2*e`. Cap(r) is at index `2*r`.\n                    \n                    // Let's update:\n                    ram_cap[2*current_edge_ptr] <= ram_cap[2*current_edge_ptr] - dfs_flow;\n                    \n                    // To update the reverse, we need to read `ram_edge_rev[current_edge_ptr]`.\n                    // We can read it in the same cycle.\n                    // Let's use a wire for rev index.\n                    // wire [10:0] rev_idx = ram_edge_rev[current_edge_ptr];\n                    \n                    // We need to perform the second write.\n                    // Can we do two writes in one state? Yes, if addresses are distinct.\n                    // We schedule both writes.\n                    \n                    // We need to be careful: `current_edge_ptr` is stable.\n                    // `ram_edge_rev[current_edge_ptr]` is read combinationally.\n                    \n                    // So:\n                    ram_cap[2*ram_edge_rev[current_edge_ptr]] <= ram_cap[2*ram_edge_rev[current_edge_ptr]] + dfs_flow;\n                    \n                    // Add to total flow\n                    current_flow <= current_flow + dfs_flow;\n                    \n                    // Check if we need to continue updating the path\n                    if (stack_ptr == 0) begin\n                        state <= DFS_INIT;\n                    end else begin\n                        state <= DFS_UPDATE_PATH;\n                    end\n                end\n\n                // CALC_PROFIT\n                CALC_PROFIT: begin\n                    // max_profit = total_positive_B - current_flow\n                    // But we need total_positive_B. We didn't calculate it!\n                    // We need to accumulate it during Load Node.\n                    // In LOAD_NODE_S: if B>0, total_positive_B <= total_positive_B + B_val.\n                    \n                    max_profit <= total_positive_B - current_flow;\n                    state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1;\n                    if (start) begin\n                        // If user wants to restart?\n                        // Or stay done.\n                        state <= DONE_STATE;\n                    end\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    // --- Helper Logic for Loading ---\n    // We need to update total_positive_B.\n    // This happens in LOAD_NODE_S.\n    // We need to detect B_val > 0.\n    // We can add this logic to the FSM block, or use a combinational block.\n    // Since we are in a sequential block, we can add it inside LOAD_NODE_S.\n    // But we already wrote the code for LOAD_NODE_S.\n    // Let's add the accumulation there.\n    \n    // We need to modify the code inside LOAD_NODE_S:\n    // if (B_val > 0) ...\n    // total_positive_B <= total_positive_B + B_val;\n    \n    // Also, we need to handle the `start` signal for transitions.\n    // In IDLE, we check `start_pulse`.\n    // If `load_mode==0` and `node_idx < 300`, we go to LOAD_NODE_S.\n    // If `load_mode==1` and `edge_idx < 300`, we go to LOAD_EDGE_1.\n    // If `load_mode==0` and `node_idx == 511`, we set `nodes_loaded_flag`.\n    // If `load_mode==1` and `edge_idx == 511`, we go to START_DINIC.\n    \n    // We need to ensure that if `start` is pressed while loading, we don't restart.\n    \n    // We also need to handle the `total_positive_B` reset.\n    // In IDLE (Reset), `total_positive_B` should be 0.\n\n    // Let's put it all together in the final code block.\n    // Note: The code above is a mix of comments and logic. We need to provide a clean Verilog module.\n    // I will assemble the code in the final response.\n\n    // Final check on parameters:\n    // S_NODE = 300 (Wait, if we split nodes, 0..299 are input, 300..599 are output.\n    // So S should be 600. T=601.\n    // I used S_NODE=300 in the logic above, assuming standard nodes.\n    // I need to fix this. \n    // If we split nodes:\n    // Input node `i`: index `i` (0..299)\n    // Output node `i`: index `i+300` (300..599)\n    // Source `S`: index `600`\n    // Sink `T`: index `601`\n    // So `node_idx` from input (0..299) maps to `i` and `i+300`.\n    \n    // In LOAD_NODE_S: \n    //   S is 600. Target is `node_idx`. (S->i)\n    // In LOAD_NODE_T:\n    //   Source is `node_idx`. Target is 601. (i->T)\n    // In LOAD_NODE_I:\n    //   Source is `node_idx`. Target is `node_idx+300`. (i->i+N)\n    \n    // In LOAD_EDGE_1:\n    //   U_val is 1-based. Convert to 0-based.\n    //   Source = (U_val-1) + 300. Target = (V_val-1).\n    // In LOAD_EDGE_2:\n    //   Source = (V_val-1) + 300. Target = (U_val-1).\n\n    // Also, in BFS and DFS, we iterate over nodes 0..601.\n    // So `MAX_NODES` should be 602.\n    \n    // Let's adjust the code in the final JSON output.\n    // I will correct the node indices in the code.\n\n    // Also, we need to declare `temp_cnt` or similar if we use it. \n    // We decided to use separate states for loading (LOAD_NODE_S, LOAD_NODE_T, LOAD_NODE_I, etc.).\n    // So we don't need `temp_cnt`.\n\n    // We need `u_reg`, `v_reg` for BFS scanning.\n    // We need `dfs_curr_node`, `dfs_flow` for DFS.\n    // We need `stack_node`, `stack_edge`, `stack_flow`, `stack_ptr`.\n    // We need `current_edge_ptr`.\n\n    // We need to declare `total_positive_B`.\n    // We need to declare `nodes_loaded_flag`.\n\n    // We need to declare `dist` RAM (size 602).\n    // We need to declare `queue` RAM (size 602).\n    // We need `q_head`, `q_tail`.\n\n    // We need to declare `ptr` RAM (size 602) for DFS.\n    // Wait, I declared `ram_ptr` inside the block. I need to move it outside or keep it inside.\n    // To be synthesizable, registers should be declared outside the always block.\n    // But `dist` and `queue` are arrays. We can declare them inside or outside.\n    // Let's declare all registers outside.\n\nendmodule\n\n// Helper module for the RAMs is not needed if we just use logic arrays.\n// However, to be precise, I will declare the arrays as `reg` outside the always block.\n\n// Correction: The `graph_profit_maximizer` module should be self-contained.\n\n```json\n{\"code\": \"module graph_profit_maximizer (\\n    input clk,\\n    input rst_n,\\n    input start,\\n    input [8:0] node_idx,\\n    input [8:0] edge_idx,\\n    input load_mode,\\n    input signed [31:0] A_val,\\n    input signed [31:0] B_val,\\n    input [8:0] U_val,\\n    input [8:0] V_val,\\n    output reg [31:0] max_profit,\\n    output reg done\\n);\\n\\n    // Parameters\\n    // Max logical nodes: 300 (input) + 300 (output) + S + T = 602\\n    // Max edges: Approx 2000 (due to node splitting). We use 2048 slots.\\n    // Edge slots: 0 is null. 1..2047 used. Each logical edge uses 2 slots (fwd/rev).\\n    parameter S_NODE = 600;\\n    parameter T_NODE = 601;\\n    parameter INF_CAP = 32'h3FFFFFFF;\\n    parameter NULL_PTR = 11'd0;\\n\\n    // FSM States\\n    parameter IDLE = 0;\\n    parameter LOAD_NODE_S = 1;\\n    parameter LOAD_NODE_T = 2;\\n    parameter LOAD_NODE_I = 3;\\n    parameter LOAD_EDGE_1 = 4;\\n    parameter LOAD_EDGE_2 = 5;\\n    parameter START_DINIC = 6;\\n    parameter BFS_INIT = 7;\\n    parameter BFS_LOOP_CHECK = 8;\\n    parameter BFS_SCAN_PREP = 9;\\n    parameter BFS_SCAN = 10;\\n    parameter DFS_INIT = 11;\\n    parameter DFS_LOOP = 12;\\n    parameter DFS_SCAN_EDGE = 13;\\n    parameter DFS_UPDATE_PATH = 14;\\n    parameter DFS_PERFORM_UPDATE = 15;\\n    parameter CALC_PROFIT = 16;\\n    parameter DONE_STATE = 17;\\n\\n    // Internal Registers\\n    reg [4:0] state;\\n    reg [10:0] edge_ptr; // Next free edge slot index (starts at 1)\\n    reg signed [31:0] total_positive_B;\\n    reg signed [31:0] current_flow;\\n    reg nodes_loaded_flag;\\n    reg start_prev;\\n    wire start_pulse;\\n    assign start_pulse = start && !start_prev;\\n\\n    // Graph Structure RAMs (Inferred as BRAM or LUTRAM)\\n    // Head pointers for nodes 0..601 (Depth 602, Width 11)\\n    reg [10:0] ram_head [0:601];\\n    // Edge Info: {next[10:0], tgt[8:0]} (Depth 2048, Width 20)\\n    reg [19:0] ram_edge_info [0:2047];\\n    // Reverse Edge Index (Depth 2048, Width 11)\\n    reg [10:0] ram_edge_rev [0:2047];\\n    // Capacity RAM: Interleaved Fwd/Rev. Index 2*e = Fwd, 2*e+1 = Rev (Depth 4096, Width 32)\\n    reg [31:0] ram_cap [0:4095];\\n\\n    // BFS Registers\\n    reg [8:0] dist [0:601]; // Distance array\\n    reg [8:0] queue [0:601]; // BFS Queue\\n    reg [8:0] q_head, q_tail;\\n    reg [8:0] bfs_node; // Temp node for iteration\\n    reg [10:0] bfs_edge; // Temp edge for iteration\\n\\n    // DFS Registers\\n    reg [10:0] ptr [0:601]; // Pointer for adjacency list traversal (per node)\\n    reg [8:0] stack_node [0:601]; // Node stack\\n    reg [10:0] stack_edge [0:601]; // Edge index stack (edge used to reach node)\n    reg signed [31:0] stack_flow [0:601]; // Flow limit stack\\n    reg [8:0] stack_ptr;\\n    reg [8:0] dfs_curr_node;\\n    reg signed [31:0] dfs_flow;\\n    reg [10:0] current_edge_ptr; // Current edge index being processed\\n\\n    // Helper Registers for FSM\\n    reg [8:0] u_reg, v_reg;\\n\\n    // Main FSM\\n    always @(posedge clk or negedge rst_n) begin\\n        if (!rst_n) begin\\n            state <= IDLE;\\n            done <= 1;\\n            max_profit <= 0;\\n            edge_ptr <= 1;\\n            total_positive_B <= 0;\\n            current_flow <= 0;\\n            nodes_loaded_flag <= 0;\\n            start_prev <= 0;\\n            // Reset Head pointers\\n            for (integer i = 0; i < 602; i = i + 1) ram_head[i] <= 0;\\n        end else begin\\n            start_prev <= start;\\n            case (state)\\n                IDLE: begin\\n                    done <= 1;\\n                    if (start_pulse) begin\\n                        done <= 0;\\n                        if (load_mode == 0) begin\\n                            // Load Node Phase\\n                            if (node_idx < 9'd300) begin\\n                                state <= LOAD_NODE_S;\\n                            end else if (node_idx == 9'h1FF) begin\\n                                nodes_loaded_flag <= 1;\\n                                // Wait for user to switch to Edge Mode\\n                            end else begin\\n                                // If start pressed with load_mode=0 and nodes already loaded (e.g. user wants to run)\n                                // Convention: if nodes_loaded_flag is 1 and start is pressed, go to START_DINIC?\\n                                // No, user must switch to Edge Mode (load_mode=1) and signal end, or just go to run.\\n                                // Let's assume: if nodes_loaded_flag is 1 and load_mode=0 and node_idx=511, go START_DINIC.\\n                                // Or simpler: just wait for Edge Mode.\\n                                // Let's allow direct run if nodes are loaded.\\n                                if (nodes_loaded_flag) state <= START_DINIC;\\n                            end\\n                        end else begin\\n                            // Load Edge Phase\\n                            if (edge_idx < 9'd300) begin\\n                                state <= LOAD_EDGE_1;\\n                            end else if (edge_idx == 9'h1FF) begin\\n                                state <= START_DINIC;\\n                            end\\n                        end\\n                    end\\n                end\\n\\n                // --- Loading States ---\\n                LOAD_NODE_S: begin\\n                    if (B_val > 0) begin\\n                        // S -> i (Fwd)\\n                        ram_edge_info[edge_ptr] <= {ram_head[S_NODE], node_idx};\\n                        ram_edge_rev[edge_ptr] <= edge_ptr + 1;\\n                        ram_head[S_NODE] <= edge_ptr;\\n                        ram_cap[2*edge_ptr] <= B_val;\\n                        // i -> S (Rev)\\n                        ram_edge_info[edge_ptr+1] <= {ram_head[node_idx], S_NODE};\\n                        ram_edge_rev[edge_ptr+1] <= edge_ptr;\\n                        ram_head[node_idx] <= edge_ptr + 1;\\n                        ram_cap[2*edge_ptr + 1] <= 0;\\n                        total_positive_B <= total_positive_B + B_val;\\n                        edge_ptr <= edge_ptr + 2;\\n                    end\\n                    state <= LOAD_NODE_T;\\n                end\\n\\n                LOAD_NODE_T: begin\\n                    if (B_val < 0) begin\\n                        // i -> T (Fwd)\\n                        ram_edge_info[edge_ptr] <= {ram_head[node_idx], T_NODE};\\n                        ram_edge_rev[edge_ptr] <= edge_ptr + 1;\\n                        ram_head[node_idx] <= edge_ptr;\\n                        ram_cap[2*edge_ptr] <= -B_val;\\n                        // T -> i (Rev)\\n                        ram_edge_info[edge_ptr+1] <= {ram_head[T_NODE], node_idx};\\n                        ram_edge_rev[edge_ptr+1] <= edge_ptr;\\n                        ram_head[T_NODE] <= edge_ptr + 1;\\n                        ram_cap[2*edge_ptr + 1] <= 0;\\n                        edge_ptr <= edge_ptr + 2;\\n                    end\\n                    state <= LOAD_NODE_I;\\n                end\\n\\n                LOAD_NODE_I: begin\\n                    // i -> i+N (Fwd)\\n                    ram_edge_info[edge_ptr] <= {ram_head[node_idx], node_idx + 300};\\n                    ram_edge_rev[edge_ptr] <= edge_ptr + 1;\\n                    ram_head[node_idx] <= edge_ptr;\\n                    ram_cap[2*edge_ptr] <= A_val;\\n                    // i+N -> i (Rev)\\n                    ram_edge_info[edge_ptr+1] <= {ram_head[node_idx + 300], node_idx};\\n                    ram_edge_rev[edge_ptr+1] <= edge_ptr;\\n                    ram_head[node_idx + 300] <= edge_ptr + 1;\\n                    ram_cap[2*edge_ptr + 1] <= 0;\\n                    edge_ptr <= edge_ptr + 2;\\n                    state <= IDLE;\\n                end\\n\\n                LOAD_EDGE_1: begin\\n                    // u+N -> v (Fwd)\\n                    // U_val is 1-based.\\n                    ram_edge_info[edge_ptr] <= {ram_head[U_val - 1 + 300], V_val - 1};\\n                    ram_edge_rev[edge_ptr] <= edge_ptr + 1;\\n                    ram_head[U_val - 1 + 300] <= edge_ptr;\\n                    ram_cap[2*edge_ptr] <= INF_CAP;\\n                    // v -> u+N (Rev)\\n                    ram_edge_info[edge_ptr+1] <= {ram_head[V_val - 1], U_val - 1 + 300};\\n                    ram_edge_rev[edge_ptr+1] <= edge_ptr;\\n                    ram_head[V_val - 1] <= edge_ptr + 1;\\n                    ram_cap[2*edge_ptr + 1] <= 0;\\n                    edge_ptr <= edge_ptr + 2;\\n                    state <= LOAD_EDGE_2;\\n                end\\n\\n                LOAD_EDGE_2: begin\\n                    // v+N -> u (Fwd)\\n                    ram_edge_info[edge_ptr] <= {ram_head[V_val - 1 + 300], U_val - 1};\\n                    ram_edge_rev[edge_ptr] <= edge_ptr + 1;\\n                    ram_head[V_val - 1 + 300] <= edge_ptr;\\n                    ram_cap[2*edge_ptr] <= INF_CAP;\\n                    // u -> v+N (Rev)\\n                    ram_edge_info[edge_ptr+1] <= {ram_head[U_val - 1], V_val - 1 + 300};\\n                    ram_edge_rev[edge_ptr+1] <= edge_ptr;\\n                    ram_head[U_val - 1] <= edge_ptr + 1;\\n                    ram_cap[2*edge_ptr + 1] <= 0;\\n                    edge_ptr <= edge_ptr + 2;\\n                    state <= IDLE;\\n                end\\n\\n                // --- Dinic's Algorithm ---\\n                START_DINIC: begin\\n                    current_flow <= 0;\\n                    state <= BFS_INIT;\\n                end\\n\\n                BFS_INIT: begin\\n                    // Reset Dist Array and DFS pointers\\n                    if (bfs_node < 602) begin\\n                        dist[bfs_node] <= 8'hFF;\\n                        ptr[bfs_node] <= 0;\\n                        bfs_node <= bfs_node + 1;\\n                    end else begin\\n                        bfs_node <= 0;\\n                        dist[S_NODE] <= 0;\\n                        queue[0] <= S_NODE;\\n                        q_head <= 0;\\n                        q_tail <= 1;\\n                        state <= BFS_LOOP_CHECK;\\n                    end\\n                end\\n\\n                BFS_LOOP_CHECK: begin\\n                    if (q_head == q_tail) begin\\n                        if (dist[T_NODE] != 8'hFF) begin\\n                            state <= DFS_INIT;\\n                        end else begin\\n                            state <= CALC_PROFIT;\\n                        end\\n                    end else begin\\n                        u_reg <= queue[q_head];\\n                        q_head <= q_head + 1;\\n                        state <= BFS_SCAN_PREP;\\n                    end\\n                end\\n\\n                BFS_SCAN_PREP: begin\\n                    bfs_edge <= ram_head[u_reg];\\n                    state <= BFS_SCAN;\\n                end\\n\\n                BFS_SCAN: begin\\n                    if (bfs_edge != 0) begin\\n                        // Check capacity and distance\\n                        if (ram_cap[2*bfs_edge] > 0 && dist[ram_edge_info[bfs_edge][8:0]] == 8'hFF) begin\\n                            dist[ram_edge_info[bfs_edge][8:0]] <= dist[u_reg] + 1;\\n                            queue[q_tail] <= ram_edge_info[bfs_edge][8:0];\\n                            q_tail <= q_tail + 1;\\n                        end\\n                        bfs_edge <= ram_edge_info[bfs_edge][19:9]; // Next edge\\n                    end else begin\\n                        state <= BFS_LOOP_CHECK;\\n                    end\\n                end\\n\\n                DFS_INIT: begin\\n                    stack_ptr <= 0;\\n                    dfs_curr_node <= S_NODE;\\n                    dfs_flow <= 32'h7FFFFFFF;\\n                    state <= DFS_LOOP;\\n                end\\n\\n                DFS_LOOP: begin\\n                    if (dfs_curr_node == T_NODE) begin\\n                        state <= DFS_UPDATE_PATH;\\n                    end else begin\\n                        current_edge_ptr <= ptr[dfs_curr_node];\\n                        state <= DFS_SCAN_EDGE;\\n                    end\\n                end\\n\\n                DFS_SCAN_EDGE: begin\\n                    if (current_edge_ptr == 0) begin\\n                        // Backtrack\\n                        if (stack_ptr == 0) begin\\n                            state <= BFS_INIT; // No more paths in this level\\n                        end else begin\\n                            stack_ptr <= stack_ptr - 1;\\n                            dfs_curr_node <= stack_node[stack_ptr - 1];\\n                            dfs_flow <= stack_flow[stack_ptr - 1];\\n                            state <= DFS_LOOP;\\n                        end\\n                    end else begin\\n                        // Check edge validity\\n                        if (dist[ram_edge_info[current_edge_ptr][8:0]] == dist[dfs_curr_node] + 1 && \n                            ram_cap[2*current_edge_ptr] > 0) begin\\n                            // Valid edge found\\n                            stack_node[stack_ptr] <= dfs_curr_node;\\n                            stack_edge[stack_ptr] <= current_edge_ptr;\\n                            stack_flow[stack_ptr] <= dfs_flow;\\n                            stack_ptr <= stack_ptr + 1;\\n\\n                            // Advance pointer for current node\\n                            ptr[dfs_curr_node] <= ram_edge_info[current_edge_ptr][19:9];\\n\\n                            // Move to next node\\n                            dfs_curr_node <= ram_edge_info[current_edge_ptr][8:0];\\n                            if (ram_cap[2*current_edge_ptr] < dfs_flow)\\n                                dfs_flow <= ram_cap[2*current_edge_ptr];\\n                            state <= DFS_LOOP;\\n                        end else begin\\n                            // Invalid edge, skip\\n                            ptr[dfs_curr_node] <= ram_edge_info[current_edge_ptr][19:9];\\n                            state <= DFS_LOOP; // Retry with next edge\\n                        end\\n                    end\\n                end\\n\\n                DFS_UPDATE_PATH: begin\\n                    if (stack_ptr == 0) begin\\n                        state <= DFS_INIT; // Path updated, start new search\\n                    end else begin\\n                        // Get edge from stack (top is stack_ptr - 1)\\n                        // We need to process the edge at stack_ptr - 1, then decrement\\n                        current_edge_ptr <= stack_edge[stack_ptr - 1];\\n                        stack_ptr <= stack_ptr - 1;\\n                        state <= DFS_PERFORM_UPDATE;\\n                    end\\n                end\\n\\n                DFS_PERFORM_UPDATE: begin\\n                    // Update Forward Capacity\\n                    ram_cap[2*current_edge_ptr] <= ram_cap[2*current_edge_ptr] - dfs_flow;\\n                    // Update Reverse Capacity (using stored reverse index)\\n                    ram_cap[2*ram_edge_rev[current_edge_ptr]] <= ram_cap[2*ram_edge_rev[current_edge_ptr]] + dfs_flow;\\n                    // Update Total Flow\\n                    current_flow <= current_flow + dfs_flow;\\n                    // Continue if stack not empty, else go back to update loop\\n                    if (stack_ptr == 0) state <= DFS_INIT;\\n                    else state <= DFS_UPDATE_PATH;\\n                end\\n\\n                CALC_PROFIT: begin\\n                    max_profit <= total_positive_B - current_flow;\\n                    state <= DONE_STATE;\\n                end\\n\\n                DONE_STATE: begin\\n                    done <= 1;\\n                    // Stay here until reset\\n                end\\n\\n                default: state <= IDLE;\\n            endcase\\n        end\\n    end\\n\\nendmodule\"}"}
